package com.fireplatform;

import java.util.*;
import org.flywaydb.core.Flyway;
import org.junit.jupiter.api.Test;
import org.springframework.dao.DataAccessException;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.DriverManagerDataSource;
import static org.assertj.core.api.Assertions.*;

class SimEmbeddedMigrationTest {
    static final List<String> TABLES=List.of("sim_embedded_profiles","sim_embedded_profile_changes","sim_card_inventory","sim_card_inventory_changes"),RIGHTS=List.of("sim-embedded:read","sim-embedded:write","sim-inventory:read","sim-inventory:write");
    record Db(String url,JdbcTemplate jdbc){ }
    final SimCardMigrationTest fixtures=new SimCardMigrationTest();
    Db db(String target,String ordering){String url="jdbc:h2:mem:sim-embedded-migration-"+UUID.randomUUID()+";MODE=PostgreSQL;DATABASE_TO_LOWER=TRUE;DEFAULT_NULL_ORDERING="+ordering+";DB_CLOSE_DELAY=-1";var config=Flyway.configure().dataSource(url,"sa","");if(target==null)config.target("16");else config.target(target);config.load().migrate();return new Db(url,new JdbcTemplate(new DriverManagerDataSource(url,"sa","")));}
    void latest(Db db){Flyway.configure().dataSource(db.url(),"sa","").target("16").load().migrate();}
    void devices(JdbcTemplate j){new SimBindingMigrationTest().devices(j);}
    JdbcTemplate prepared(String ordering){var j=db(null,ordering).jdbc();fixtures.tenant(j);devices(j);fixtures.user(j,"actor","PLATFORM",false);return j;}
    void profile(JdbcTemplate j,String device,String tenant,String iccid,long revision){j.update("INSERT INTO sim_embedded_profiles(device_id,tenant_id,iccid,carrier_name,installation_form,replaceability,management_party,fee_responsibility,reported_operator_status,expires_on,evidence_at,source_note,information_source,revision,recorded_at) VALUES (?,?,?,'','EMBEDDED','UNKNOWN','UNKNOWN','UNKNOWN','UNKNOWN',NULL,NULL,'','MANUAL',?,TIMESTAMP WITH TIME ZONE '2026-01-02 03:04:05.123456+00:00')",device,tenant,iccid,revision);}
    void change(JdbcTemplate j,String device,String tenant,long revision,String operation){j.update("INSERT INTO sim_embedded_profile_changes(id,device_id,tenant_id,iccid,carrier_name,installation_form,replaceability,management_party,fee_responsibility,reported_operator_status,expires_on,evidence_at,source_note,information_source,revision,recorded_at,operation,reason,actor_user_id) VALUES (?,?,?,NULL,'','EMBEDDED','UNKNOWN','UNKNOWN','UNKNOWN','UNKNOWN',NULL,NULL,'','MANUAL',?,TIMESTAMP WITH TIME ZONE '2026-01-02 03:04:05.123456+00:00',?,'','actor')",UUID.randomUUID().toString(),device,tenant,revision,operation);}
    @Test void latestIsExactly54WithFourEmptyTablesAndNoImplicitManualDataSeeds(){var j=db(null,"LOW").jdbc();assertThat(fixtures.tables(j)).hasSize(54).containsAll(TABLES);for(String table:TABLES)assertThat(j.queryForObject("SELECT COUNT(*) FROM "+table,Long.class)).isZero();assertThat(j.queryForObject("SELECT COUNT(*) FROM user_permissions",Long.class)).isZero();assertThat(j.queryForList("SELECT column_name FROM information_schema.columns WHERE table_name='sim_embedded_profiles' ORDER BY ordinal_position",String.class)).containsExactly("device_id","tenant_id","iccid","carrier_name","installation_form","replaceability","management_party","fee_responsibility","reported_operator_status","expires_on","evidence_at","source_note","information_source","revision","recorded_at");assertThat(j.queryForList("SELECT column_name FROM information_schema.columns WHERE table_name='sim_embedded_profile_changes'",String.class)).hasSize(19).contains("actor_user_id","reason","operation","id");}
    @Test void v15UpgradePreservesAll50OldFactsColumnsConstraintsAndIndexesExceptFourExactRights(){var db=db("15","LOW");var j=db.jdbc();fixtures.tenant(j);devices(j);fixtures.user(j,"bootstrap-admin","PLATFORM",true);fixtures.user(j,"other-protected","PLATFORM",true);j.update("INSERT INTO user_permissions(user_id,permission) VALUES ('bootstrap-admin','sim-cards:read'),('bootstrap-admin','sim-cards:write'),('bootstrap-admin','sim-cards:bind'),('other-protected','device:read')");String card=fixtures.card(j,"a","000Legacy");new SimBindingMigrationTest().current(j,card,"a","a-legacy-device-0",1);var old=fixtures.tables(j);assertThat(old).hasSize(50);var before=fixtures.facts(j,old);var columns=j.queryForList("SELECT table_name,column_name,data_type,is_nullable FROM information_schema.columns WHERE table_schema='public' ORDER BY table_name,ordinal_position");var constraints=j.queryForList("SELECT table_name,constraint_name,constraint_type FROM information_schema.table_constraints WHERE table_schema='public' ORDER BY table_name,constraint_name");var indexes=j.queryForList("SELECT * FROM information_schema.indexes WHERE table_schema='public' ORDER BY table_name,index_name");latest(db);assertThat(fixtures.tables(j)).hasSize(54).containsAll(old);var after=fixtures.facts(j,old);after.put("user_permissions",j.queryForList("SELECT * FROM user_permissions WHERE permission NOT IN ('sim-embedded:read','sim-embedded:write','sim-inventory:read','sim-inventory:write')"));assertThat(after).isEqualTo(before);assertThat(j.queryForList("SELECT permission FROM user_permissions WHERE permission LIKE 'sim-embedded:%' OR permission LIKE 'sim-inventory:%' ORDER BY permission",String.class)).containsExactlyElementsOf(RIGHTS);assertThat(j.queryForList("SELECT DISTINCT user_id FROM user_permissions WHERE permission LIKE 'sim-embedded:%' OR permission LIKE 'sim-inventory:%'",String.class)).containsExactly("bootstrap-admin");String oldOnly=" AND table_name NOT IN ('sim_embedded_profiles','sim_embedded_profile_changes','sim_card_inventory','sim_card_inventory_changes')";assertThat(j.queryForList("SELECT table_name,column_name,data_type,is_nullable FROM information_schema.columns WHERE table_schema='public'"+oldOnly+" ORDER BY table_name,ordinal_position")).isEqualTo(columns);assertThat(j.queryForList("SELECT table_name,constraint_name,constraint_type FROM information_schema.table_constraints WHERE table_schema='public'"+oldOnly+" ORDER BY table_name,constraint_name")).isEqualTo(constraints);assertThat(j.queryForList("SELECT * FROM information_schema.indexes WHERE table_schema='public'"+oldOnly+" ORDER BY table_name,index_name")).isEqualTo(indexes);}
    @Test void fourGrantsRequireAllExactRootConditionsAndNeverGrantOtherProtectedAccounts(){for(String type:List.of("PLATFORM","CUSTOMER"))for(boolean protectedUser:List.of(false,true)){var db=db("15","LOW");var j=db.jdbc();fixtures.tenant(j);fixtures.user(j,"bootstrap-admin",type,protectedUser);fixtures.user(j,"other-protected","PLATFORM",true);latest(db);assertThat(j.queryForObject("SELECT COUNT(*) FROM user_permissions",Long.class)).isEqualTo(type.equals("PLATFORM")&&protectedUser?4L:0L);}}
    @Test void absentRootExistingRightsAndRepeatedMigrationNeverSeedOrDuplicate(){var absent=db("15","LOW");latest(absent);assertThat(absent.jdbc().queryForObject("SELECT COUNT(*) FROM app_users",Long.class)).isZero();var db=db("15","HIGH");var j=db.jdbc();fixtures.tenant(j);fixtures.user(j,"bootstrap-admin","PLATFORM",true);for(String right:RIGHTS)j.update("INSERT INTO user_permissions(user_id,permission) VALUES ('bootstrap-admin',?)",right);latest(db);var before=fixtures.facts(j,fixtures.tables(j));latest(db);latest(db);assertThat(fixtures.facts(j,fixtures.tables(j))).isEqualTo(before);assertThat(j.queryForObject("SELECT COUNT(*) FROM flyway_schema_history WHERE version='16' AND success=TRUE",Long.class)).isEqualTo(1);assertThat(j.queryForObject("SELECT COUNT(*) FROM user_permissions",Long.class)).isEqualTo(4);}
    @Test void onlyIccidAndTwoDatesAreNullableAndDatabaseInstantsHaveSixDigits(){var j=db(null,"LOW").jdbc();for(String table:List.of("sim_embedded_profiles","sim_embedded_profile_changes")){assertThat(j.queryForList("SELECT column_name FROM information_schema.columns WHERE table_name=? AND is_nullable='YES' ORDER BY column_name",String.class,table)).containsExactly("evidence_at","expires_on","iccid");assertThat(j.queryForList("SELECT datetime_precision FROM information_schema.columns WHERE table_name=? AND column_name IN ('evidence_at','recorded_at')",Integer.class,table)).containsExactlyInAnyOrder(6,6);assertThat(j.queryForObject("SELECT data_type FROM information_schema.columns WHERE table_name=? AND column_name='expires_on'",String.class,table)).isEqualToIgnoringCase("date");}}
    @Test void nullAndDuplicateReportedIccidsAreAllowedWithoutCreatingCardEntities(){for(String ordering:List.of("LOW","HIGH")){var j=prepared(ordering);profile(j,"a-legacy-device-0","a",null,1);profile(j,"a-legacy-device-1","a",null,1);j.update("UPDATE sim_embedded_profiles SET iccid='000SameReport'");assertThat(j.queryForObject("SELECT COUNT(*) FROM sim_embedded_profiles WHERE iccid='000SameReport'",Long.class)).isEqualTo(2);assertThat(j.queryForObject("SELECT COUNT(*) FROM sim_cards",Long.class)).isZero();assertThat(j.queryForObject("SELECT COUNT(*) FROM sim_card_associations",Long.class)).isZero();}}
    @Test void profileAndHistoryCompositeTenantKeysRejectCrossTenantAndMissingParents(){var j=prepared("HIGH");assertThatThrownBy(()->profile(j,"a-legacy-device-0","b",null,1)).isInstanceOf(DataAccessException.class);assertThatThrownBy(()->profile(j,"missing-device","a",null,1)).isInstanceOf(DataAccessException.class);profile(j,"a-legacy-device-0","a",null,1);assertThatThrownBy(()->change(j,"a-legacy-device-0","b",1,"RECORD")).isInstanceOf(DataAccessException.class);assertThatThrownBy(()->change(j,"a-legacy-device-1","a",1,"RECORD")).isInstanceOf(DataAccessException.class);change(j,"a-legacy-device-0","a",1,"RECORD");assertThatThrownBy(()->j.update("DELETE FROM sim_embedded_profiles WHERE device_id='a-legacy-device-0'")).isInstanceOf(DataAccessException.class);}
    @Test void physicalZeroUnsafeRevisionWrongTypeSourceOperationAndDuplicateHistoryAreRejected(){var j=prepared("LOW");assertThatThrownBy(()->profile(j,"a-legacy-device-0","a",null,0)).isInstanceOf(DataAccessException.class);assertThatThrownBy(()->profile(j,"a-legacy-device-0","a",null,9_007_199_254_740_992L)).isInstanceOf(DataAccessException.class);profile(j,"a-legacy-device-0","a",null,1);for(String field:List.of("installation_form","information_source","replaceability","management_party","fee_responsibility","reported_operator_status"))assertThatThrownBy(()->j.update("UPDATE sim_embedded_profiles SET "+field+"='WRONG'")).isInstanceOf(DataAccessException.class);assertThatThrownBy(()->change(j,"a-legacy-device-0","a",1,"CREATE")).isInstanceOf(DataAccessException.class);change(j,"a-legacy-device-0","a",1,"RECORD");assertThatThrownBy(()->change(j,"a-legacy-device-0","a",1,"RECORD")).isInstanceOf(DataAccessException.class);assertThatThrownBy(()->j.update("UPDATE sim_embedded_profile_changes SET id='NOT-UUID'")).isInstanceOf(DataAccessException.class);}
}
